-- ---------------------------------------------------------------------------
-- Hardening (not expressible in the Prisma schema)
-- ---------------------------------------------------------------------------

ALTER TABLE "aurelia"."staff_members"
  ADD CONSTRAINT "staff_members_email_lower_check" CHECK ("email" = lower("email")),
  ADD CONSTRAINT "staff_members_name_check" CHECK (char_length(btrim("full_name")) BETWEEN 1 AND 80);

ALTER TABLE "aurelia"."villas"
  ADD CONSTRAINT "villas_slug_check" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "villas_numbers_check" CHECK (
    "built_up_area" > 0 AND "plot_area" > 0 AND "bedrooms" >= 0 AND "bathrooms" >= 0
    AND "floors" > 0 AND "car_parks" >= 0 AND "unit_count" >= 0 AND "starting_price" >= 0);

ALTER TABLE "aurelia"."construction_updates"
  ADD CONSTRAINT "construction_updates_progress_check" CHECK ("overall_progress" BETWEEN 0 AND 100);

ALTER TABLE "aurelia"."media_assets"
  ADD CONSTRAINT "media_assets_bytes_check" CHECK ("bytes" > 0 AND "width" > 0 AND "height" > 0);

-- updated_at maintained by the database too (function from the first migration).
CREATE TRIGGER "staff_members_set_updated_at" BEFORE UPDATE ON "aurelia"."staff_members"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."set_updated_at"();
CREATE TRIGGER "villas_set_updated_at" BEFORE UPDATE ON "aurelia"."villas"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."set_updated_at"();
CREATE TRIGGER "gallery_items_set_updated_at" BEFORE UPDATE ON "aurelia"."gallery_items"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."set_updated_at"();
CREATE TRIGGER "construction_updates_set_updated_at" BEFORE UPDATE ON "aurelia"."construction_updates"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."set_updated_at"();
CREATE TRIGGER "construction_milestones_set_updated_at" BEFORE UPDATE ON "aurelia"."construction_milestones"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."set_updated_at"();
CREATE TRIGGER "content_entries_set_updated_at" BEFORE UPDATE ON "aurelia"."content_entries"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."set_updated_at"();

-- Audit log is append-only: rows can be inserted but never changed or removed.
CREATE FUNCTION "aurelia"."audit_logs_immutable"() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only';
END;
$$;
CREATE TRIGGER "audit_logs_no_update" BEFORE UPDATE OR DELETE ON "aurelia"."audit_logs"
  FOR EACH ROW EXECUTE FUNCTION "aurelia"."audit_logs_immutable"();
CREATE TRIGGER "audit_logs_no_truncate" BEFORE TRUNCATE ON "aurelia"."audit_logs"
  FOR EACH STATEMENT EXECUTE FUNCTION "aurelia"."audit_logs_immutable"();

